-- ============================================
-- Migration: 202606020002_import_portfolio_row_rpc.sql
-- ============================================
-- Script independiente: crear RPC import_credit_portfolio_row
-- Verifica dependencias antes de crear la función

DO $$
DECLARE
  v_missing text := '';
BEGIN
  IF to_regclass('public.credit_accounts') IS NULL THEN
    v_missing := v_missing || 'credit_accounts; ';
  END IF;
  IF to_regclass('public.credit_installments') IS NULL THEN
    v_missing := v_missing || 'credit_installments; ';
  END IF;
  IF to_regclass('public.credit_payment_allocations') IS NULL THEN
    v_missing := v_missing || 'credit_payment_allocations; ';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'credit_accounts' AND column_name = 'operation_number'
  ) THEN
    v_missing := v_missing || 'credit_accounts.operation_number; ';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname = 'generate_credit_installments'
  ) THEN
    v_missing := v_missing || 'generate_credit_installments; ';
  END IF;

  IF v_missing <> '' THEN
    RAISE EXCEPTION 'Dependencias faltantes: %', v_missing;
  END IF;
END $$;

CREATE OR REPLACE FUNCTION import_credit_portfolio_row(p_data jsonb)
RETURNS TABLE (
  credit_account_id uuid,
  customer_id uuid,
  payments_imported integer
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_customer_id uuid;
  v_credit_account_id uuid;
  v_payment jsonb;
  v_payment_id uuid;
  v_remaining_to_allocate numeric(12, 2);
  v_allocation_amount numeric(12, 2);
  v_installment record;
  v_payments_count integer := 0;
  v_phone text;
  v_full_name text;
BEGIN
  -- normalize customer inputs from camelCase payload
  v_phone := nullif(trim(p_data->>'customerPhone'), '');
  v_full_name := nullif(trim(p_data->>'customerFullName'), '');

  -- find by phone
  if v_phone is not null then
    select id into v_customer_id from customers where phone = v_phone limit 1;
  end if;

  -- find by full_name if no phone match
  if v_customer_id is null and v_full_name is not null then
    select id into v_customer_id from customers where full_name = v_full_name limit 1;
  end if;

  -- create customer if not found
  if v_customer_id is null then
    insert into customers (
      full_name,
      phone,
      address,
      city,
      notes
    ) values (
      coalesce(v_full_name, 'Cliente sin nombre'),
      v_phone,
      nullif(trim(p_data->>'customerAddress'), ''),
      nullif(trim(p_data->>'betweenStreets'), ''),
      nullif(trim(p_data->>'betweenStreets'), '')
    )
    returning id into v_customer_id;
  end if;

  -- insert credit account (camelCase keys)
  insert into credit_accounts (
    customer_id,
    operation_number,
    product_name,
    quantity,
    installment_count,
    installment_amount,
    sale_date,
    notes
  ) values (
    v_customer_id,
    nullif(trim(p_data->>'operationNumber'), ''),
    coalesce(nullif(trim(p_data->>'productName'), ''), 'Artículo no especificado'),
    1,
    (p_data->>'installmentCount')::integer,
    (p_data->>'installmentAmount')::numeric,
    coalesce((p_data->>'saleDate')::date, current_date),
    nullif(trim(p_data->>'notes'), '')
  )
  returning id into v_credit_account_id;

  -- generate installments
  perform generate_credit_installments(
    v_credit_account_id,
    (p_data->>'installmentCount')::integer,
    (p_data->>'installmentAmount')::numeric,
    coalesce((p_data->>'saleDate')::date, current_date)
  );

  -- process historical payments (camelCase keys inside payment objects)
  for v_payment in select value from jsonb_array_elements(p_data->'payments') loop
    insert into credit_payments (
      credit_account_id,
      amount,
      payment_date,
      payment_method,
      notes
    ) values (
      v_credit_account_id,
      (v_payment->>'amount')::numeric,
      (v_payment->>'paymentDate')::date,
      coalesce(nullif(trim(v_payment->>'paymentMethod'), ''), 'EFECTIVO'),
      nullif(trim(v_payment->>'notes'), '')
    )
    returning id into v_payment_id;

    v_remaining_to_allocate := (v_payment->>'amount')::numeric;

    for v_installment in
      select * from credit_installments
      where credit_account_id = v_credit_account_id
        and remaining_amount > 0
      order by installment_number asc
      for update
    loop
      exit when v_remaining_to_allocate <= 0;

      v_allocation_amount := least(v_remaining_to_allocate, v_installment.remaining_amount);

      insert into credit_payment_allocations (
        credit_payment_id,
        credit_installment_id,
        amount
      ) values (
        v_payment_id,
        v_installment.id,
        v_allocation_amount
      );

      update credit_installments
      set
        paid_amount = paid_amount + v_allocation_amount,
        remaining_amount = remaining_amount - v_allocation_amount,
        status = case when remaining_amount - v_allocation_amount = 0 then 'PAID' else 'PARTIAL' end,
        updated_at = now()
      where id = v_installment.id;

      v_remaining_to_allocate := v_remaining_to_allocate - v_allocation_amount;
    end loop;

    v_payments_count := v_payments_count + 1;
  end loop;

  return query select v_credit_account_id, v_customer_id, v_payments_count;
END;
$$;

-- ============================================
-- Migration: 202606050001_credit_portfolio_clean_and_metrics.sql
-- ============================================
-- Migration: Portfolio cleanup and commercial metrics
-- Adds transactional cleanup RPC and commercial metrics for credit portfolio
--
-- IMPORTANTE: Esta migración debe ejecutarse manualmente en Supabase.
-- Ver la sección "Cómo aplicar" al final del archivo.
--
-- Seguridad: Se envuelve en BEGIN/COMMIT para atomicidad.
-- Se usa DROP IF EXISTS antes de cada CREATE para permitir
-- cambios de return type entre ejecuciones.

BEGIN;

-- ============================================================================
-- DROP functions (if exist with different signatures)
-- ============================================================================
DROP FUNCTION IF EXISTS get_credit_clean_summary();
DROP FUNCTION IF EXISTS clean_credit_portfolio();
DROP FUNCTION IF EXISTS get_credit_commercial_metrics();
DROP FUNCTION IF EXISTS get_credit_monthly_control();

-- ============================================================================
-- 1. Summary before cleanup: counts of portfolio tables
-- ============================================================================
CREATE OR REPLACE FUNCTION get_credit_clean_summary()
RETURNS TABLE (
  allocation_count bigint,
  payment_count bigint,
  installment_count bigint,
  account_count bigint,
  customer_count bigint
)
LANGUAGE SQL
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT
    (SELECT COUNT(*) FROM credit_payment_allocations),
    (SELECT COUNT(*) FROM credit_payments),
    (SELECT COUNT(*) FROM credit_installments),
    (SELECT COUNT(*) FROM credit_accounts),
    (SELECT COUNT(*) FROM customers);
$$;

-- ============================================================================
-- 2. Transactional cleanup of the entire portfolio (keeps users, profiles, products, etc.)
-- ============================================================================
CREATE OR REPLACE FUNCTION clean_credit_portfolio()
RETURNS TABLE (
  allocations_deleted bigint,
  payments_deleted bigint,
  installments_deleted bigint,
  accounts_deleted bigint,
  customers_deleted bigint
)
LANGUAGE PLPGSQL
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_allocations bigint;
  v_payments bigint;
  v_installments bigint;
  v_accounts bigint;
BEGIN
  DELETE FROM credit_payment_allocations WHERE true;
  GET DIAGNOSTICS v_allocations = ROW_COUNT;

  DELETE FROM credit_payments WHERE true;
  GET DIAGNOSTICS v_payments = ROW_COUNT;

  DELETE FROM credit_installments WHERE true;
  GET DIAGNOSTICS v_installments = ROW_COUNT;

  DELETE FROM credit_accounts WHERE true;
  GET DIAGNOSTICS v_accounts = ROW_COUNT;

  RETURN QUERY SELECT v_allocations, v_payments, v_installments, v_accounts, 0::bigint;
EXCEPTION WHEN OTHERS THEN
  RAISE;
END;
$$;

-- ============================================================================
-- 3. Commercial metrics for the dashboard
--
-- Business definitions:
--   current_monthly_collection = SUM(credit_payments.amount) where payment_date is in the current month
--   monthly_replacement        = SUM(credit_accounts.installment_amount) where sale_date is in the current month
--   finished_cards             = COUNT(*) of accounts with total_paid >= total_financed and last payment in current month
--   finished_installments_amount = SUM(installment_amount) of those finished accounts
--   projected_next_month       = current_monthly_collection + monthly_replacement - finished_installments_amount
-- ============================================================================
CREATE OR REPLACE FUNCTION get_credit_commercial_metrics()
RETURNS TABLE (
  current_monthly_collection numeric,
  monthly_replacement numeric,
  finished_cards integer,
  finished_installments_amount numeric,
  projected_next_month numeric
)
LANGUAGE SQL
SECURITY DEFINER
SET search_path = public
AS $$
WITH month_bounds AS (
  SELECT
    DATE_TRUNC('month', NOW()) AS month_start,
    DATE_TRUNC('month', NOW()) + INTERVAL '1 month' AS month_end
),
account_aggregates AS (
  SELECT
    ca.id,
    ca.installment_amount,
    ca.sale_date,
    (ca.installment_amount * ca.installment_count)::numeric AS total_financed,
    COALESCE(SUM(cp.amount), 0)::numeric AS total_paid,
    MAX(cp.payment_date) AS last_payment_date
  FROM credit_accounts ca
  LEFT JOIN credit_payments cp ON cp.credit_account_id = ca.id
  GROUP BY ca.id, ca.installment_amount, ca.installment_count, ca.sale_date
)
SELECT
  COALESCE((
    SELECT SUM(cp.amount)::numeric
    FROM credit_payments cp
    CROSS JOIN month_bounds mb
    WHERE cp.payment_date >= mb.month_start
      AND cp.payment_date < mb.month_end
  ), 0)::numeric AS current_monthly_collection,

  COALESCE(SUM(
    CASE WHEN aa.sale_date >= mb.month_start AND aa.sale_date < mb.month_end
         THEN aa.installment_amount ELSE 0 END
  ), 0)::numeric AS monthly_replacement,

  COALESCE(SUM(
    CASE WHEN aa.total_paid >= aa.total_financed
          AND aa.last_payment_date >= mb.month_start
          AND aa.last_payment_date < mb.month_end
         THEN 1 ELSE 0 END
  ), 0)::integer AS finished_cards,

  COALESCE(SUM(
    CASE WHEN aa.total_paid >= aa.total_financed
          AND aa.last_payment_date >= mb.month_start
          AND aa.last_payment_date < mb.month_end
         THEN aa.installment_amount ELSE 0 END
  ), 0)::numeric AS finished_installments_amount,

  (
    COALESCE((
      SELECT SUM(cp.amount)::numeric
      FROM credit_payments cp
      CROSS JOIN month_bounds mb
      WHERE cp.payment_date >= mb.month_start
        AND cp.payment_date < mb.month_end
    ), 0)
    + COALESCE(SUM(
        CASE WHEN aa.sale_date >= mb.month_start AND aa.sale_date < mb.month_end
             THEN aa.installment_amount ELSE 0 END
      ), 0)
    - COALESCE(SUM(
        CASE WHEN aa.total_paid >= aa.total_financed
              AND aa.last_payment_date >= mb.month_start
              AND aa.last_payment_date < mb.month_end
             THEN aa.installment_amount ELSE 0 END
      ), 0)
  )::numeric AS projected_next_month
FROM account_aggregates aa, month_bounds mb;
$$;

-- ============================================================================
-- 4. Monthly control report rows
-- ============================================================================
CREATE OR REPLACE FUNCTION get_credit_monthly_control()
RETURNS TABLE (
  customer_name text,
  operation_number text,
  product_name text,
  installment_amount numeric,
  status text,
  sale_date date,
  last_payment_date date,
  remaining_amount numeric
)
LANGUAGE SQL
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT
    c.full_name AS customer_name,
    ca.operation_number,
    ca.product_name,
    ca.installment_amount,
    CASE
      WHEN (ca.installment_amount * ca.installment_count) <= COALESCE(SUM(cp.amount), 0) THEN 'Finalizada'
      WHEN ca.sale_date >= DATE_TRUNC('month', NOW()) THEN 'Nueva'
      ELSE 'En curso'
    END AS status,
    ca.sale_date::date,
    MAX(cp.payment_date)::date AS last_payment_date,
    (ca.installment_amount * ca.installment_count - COALESCE(SUM(cp.amount), 0))::numeric AS remaining_amount
  FROM credit_accounts ca
  LEFT JOIN customers c ON c.id = ca.customer_id
  LEFT JOIN credit_payments cp ON cp.credit_account_id = ca.id
  WHERE ca.is_active = true
  GROUP BY ca.id, c.full_name, ca.operation_number, ca.product_name, ca.installment_amount, ca.installment_count, ca.sale_date
  ORDER BY ca.sale_date DESC;
$$;

