  using (
    credit_account_id in (
      select ca.id from credit_accounts ca
      join customers c on c.id = ca.customer_id
      where c.user_id = auth.uid()
    )
  );

-- ============================================
-- Migration: 202607290001_allow_multiple_customers_per_user.sql
-- ============================================
-- Allow multiple customers per auth user (remove unique constraint on user_id)
drop index if exists idx_customers_user_id;
create index if not exists idx_customers_user_id on customers(user_id);

-- ============================================
-- Migration: 202607310001_product_soft_delete.sql
-- ============================================
-- =============================================================================
-- MIGRACIÓN: Sistema de Papelera (Soft Delete) para productos
-- Fecha: 2026-07-31
--
-- Objetivo: permitir mover productos a la papelera sin eliminarlos físicamente.
--   - deleted_at    timestamptz null : fecha en que se movió a la papelera (NULL = activo)
--   - deleted_by    uuid null        : usuario (auth.users.id) que lo movió
--   - delete_reason text null        : motivo opcional
--
-- No se elimina ninguna columna existente ni se modifican migraciones previas.
-- =============================================================================

alter table products
  add column if not exists deleted_at timestamptz,
  add column if not exists deleted_by uuid references auth.users(id) on delete set null,
  add column if not exists delete_reason text;

-- Índices de soporte para los listados (activos y papelera)
create index if not exists idx_products_deleted_at
  on products (deleted_at)
  where deleted_at is null;

create index if not exists idx_products_deleted_by
  on products (deleted_by)
  where deleted_by is not null;

comment on column products.deleted_at is 'Soft delete: fecha en que el producto fue movido a la papelera. NULL = producto activo.';
comment on column products.deleted_by is 'Soft delete: usuario (auth.users.id) que movió el producto a la papelera.';
comment on column products.delete_reason is 'Soft delete: motivo opcional al mover el producto a la papelera.';

-- ============================================
-- Migration: 202607310002_product_price_history.sql
-- ============================================
-- ETAPA 13: Historial de precios de productos.
-- Tabla dedicada (no se reutiliza admin_audit_logs para el historial).

create table if not exists product_price_history (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references products(id) on delete cascade,
  old_price numeric(10,2) not null,
  new_price numeric(10,2) not null,
  changed_by uuid null references auth.users(id) on delete set null,
  reason text null,
  created_at timestamptz not null default now()
);

create index if not exists idx_product_price_history_product_id
  on product_price_history (product_id);

create index if not exists idx_product_price_history_created_at
  on product_price_history (created_at desc);

comment on table product_price_history is
  'Historial de cambios de precio de productos. Registra un cambio por modificacion real de precio.';

comment on column product_price_history.old_price is 'Precio anterior al cambio.';
comment on column product_price_history.new_price is 'Precio nuevo despues del cambio.';
comment on column product_price_history.reason is 'Motivo opcional indicado por el administrador.';

-- RLS: solo lectura para ADMIN/STAFF; el resto del acceso es via service-role.
alter table product_price_history enable row level security;

drop policy if exists "Admin can read product_price_history" on product_price_history;

create policy "Admin can read product_price_history"
  on product_price_history for select
  using (exists (
    select 1 from profiles
    where user_id = auth.uid()
      and role in ('ADMIN', 'STAFF')
      and is_active = true
  ));

-- ============================================
-- Migration: 202608030001_restrict_profiles_self_update.sql
-- ============================================
-- M1: Cerrar la escalada de rol vía RLS en profiles.
--
-- Problema verificado: la política "Users can update own basic profile"
-- (creada en 202605260004_rls.sql) permitía a cualquier usuario autenticado
-- actualizar su propia fila en profiles SIN restringir columnas. Como RLS es
-- a nivel fila (no columna), un usuario podía ejecutar
--   UPDATE profiles SET role = 'ADMIN'
-- sobre su propia fila usando la anon key + sesión del browser client.
-- Eso escalaba privilegios a ADMIN/STAFF y daba acceso al panel admin y a las
-- APIs /api/admin/*.
--
-- Fix conservador: restringir el UPDATE a nivel de columnas. El rol
-- authenticated solo puede actualizar full_name de su propia fila (se preserva
-- la intención original de la política: editar el "perfil básico"). role e
-- is_active quedan inmutables para escrituras client-side.
--
-- No afecta los writes legítimos:
--   * handle_new_auth_user (trigger) y toggle_user_active_atomic (RPC) son
--     SECURITY DEFINER: corren como owner de la función, sin RLS ni column grants.
--   * service_role (usado por las APIs admin) no se ve afectado por este revoke.
--   * No hay INSERT ni DELETE policies sobre profiles: el cliente no puede
--     insertar ni borrar filas (default deny por RLS).

revoke update on profiles from anon, authenticated;
grant update (full_name) on profiles to authenticated;

-- ============================================
-- Migration: 202608060001_handle_new_auth_user.sql
-- ============================================
-- W07 (B/C3): incorporar a las migraciones el alta automática de perfiles.
--
-- Problema: handle_new_auth_user() + trigger on_auth_user_created sobre
-- auth.users existían solo en supabase/schema.sql (snapshot manual de Fase 1),
-- nunca en las migraciones versionadas. Un proyecto reconstruido solo con
-- migraciones quedaba sin alta automática de profiles: signUp creaba la fila en
-- auth.users pero ningún profile, y el login posterior devolvía "Cuenta
-- desactivada" (lib/authContext.tsx).
--
-- Estrategia:
--   1. Función idéntica a la definición histórica probada (schema.sql backup).
--      SECURITY DEFINER: profiles tiene RLS sin policy de INSERT y sin grants de
--      INSERT para anon/authenticated (ver 202608030001); el INSERT solo puede
--      ocurrir como owner de la tabla, atravesando RLS.
--   2. Trigger drop-if-exists + create: seguro ante doble ejecución y sobre una
--      base donde ya exista (se re-apunta al objeto actual, sin duplicarlo).
--   3. Backfill idempotente para auth.users huérfanos (sin fila en profiles):
--      anti-join + on conflict do nothing => re-ejecutable, sin duplicados.
--
-- Compatibilidad: no toca RLS, policies, grants, roles, storage ni otras
-- funciones. No modifica migraciones existentes.

create or replace function handle_new_auth_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into profiles (user_id, role, full_name)
  values (
    new.id,
    'CUSTOMER',
    coalesce(new.raw_user_meta_data->>'full_name', new.email)
  )
  on conflict (user_id) do nothing;

  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function handle_new_auth_user();

-- Backfill idempotente: perfiles para auth.users existentes sin profile.
-- En una DB nueva no inserta nada. Re-ejecutable sin riesgo de duplicados.
insert into profiles (user_id, role, full_name, is_active)
select
  u.id,
  'CUSTOMER',
  coalesce(u.raw_user_meta_data->>'full_name', u.email),
  true
from auth.users u
left join profiles p on p.user_id = u.id
where p.user_id is null
on conflict (user_id) do nothing;

-- ============================================
-- Migration: 202608060002_products_reference_price_tendencias.sql
-- ============================================
-- W08 (B/C4): alinear products.reference_price y products.tendencias con el esquema.
--
-- Problema: la app usa `products.reference_price` y `products.tendencias` en
-- lectura y escritura (catálogo admin, secciones "Tendencias" del home,
-- importador de URLs, formulario de producto) pero no existían en ningún DDL
-- versionado (migraciones ni schema.sql): eran columnas creadas a mano en la
-- base real y nunca migradas (ver ETAPA_B C4).
--
-- Estrategia (Opción A): las columnas son necesarias y tienen callers vivos;
-- se incorporan al DDL oficial con el mismo patrón idempotente usado en
-- 202607310001 (add column if not exists), de modo que es seguro ejecutar esta
-- migración sobre una base donde las columnas ya existan (prod).
--
-- Tipos elegidos según el código:
--   * reference_price numeric(12,2) NULL        -> catalogAdapter: number | null
--   * tendencias      boolean NOT NULL default false -> lib/types.ts: boolean
--                                                  (adapter usa `?? false`)
--
-- No toca RLS, policies, grants, storage ni otras tablas. No modifica
-- migraciones existentes.

alter table products
  add column if not exists reference_price numeric(12,2),
  add column if not exists tendencias boolean not null default false;

comment on column products.reference_price is 'Precio de referencia opcional (normalmente el precio de lista de la fuente de importación).';
comment on column products.tendencias is 'Destaca el producto en las secciones de Tendencias del home (Hogar/Blanqueria).';
